//--- ENUM MONEY MANAGEMENT
enum ENUM_MM_TYPE
  {
   MM_FIXED_LOT    = 0, // Fixed Lot Size
   MM_RISK_PERCENT = 1  // Risk Percent (% per Trade)
  };

enum ENUM_RISK_BASE
  {
   RISK_BASE_BALANCE = 0, // Account Balance
   RISK_BASE_EQUITY  = 1  // Account Equity
  };

