      return Q_YELLOW;
   if(g_margin_level_text=="WARNING")
      return Q_ORANGE;
   return Q_RED;
  }

void ClassifyMarginUse()
  {
   if(g_margin_use_pct<=InpSafeMarginUsePct)
      g_margin_level_text="SAFE";
   else if(g_margin_use_pct<=InpWarningMarginUsePct)
      g_margin_level_text="MODERATE";
   else if(g_margin_use_pct<=InpDangerMarginUsePct)
      g_margin_level_text="WARNING";
   else
      g_margin_level_text="DANGEROUS";
  }

bool CalculateMargin()
  {
   g_symbol=SelectedSymbol();

   if(!SymbolSelect(g_symbol,true))
     {
      g_status="SYMBOL NOT AVAILABLE";
      g_error_count++;
      return false;
     }

   if(InpLotSize<=0.0)
     {
      g_status="SET VALID LOT SIZE";
      return false;
     }

   g_price=ResolvePrice(g_symbol);

   if(g_price<=0.0)
     {
      g_status="INVALID PRICE";
      g_error_count++;
      return false;
     }

   g_contract_size=SymbolInfoDouble(g_symbol,SYMBOL_TRADE_CONTRACT_SIZE);
   g_tick_value=SymbolInfoDouble(g_symbol,SYMBOL_TRADE_TICK_VALUE);
   g_tick_size=SymbolInfoDouble(g_symbol,SYMBOL_TRADE_TICK_SIZE);
   g_volume_min=SymbolInfoDouble(g_symbol,SYMBOL_VOLUME_MIN);
   g_volume_max=SymbolInfoDouble(g_symbol,SYMBOL_VOLUME_MAX);
   g_volume_step=SymbolInfoDouble(g_symbol,SYMBOL_VOLUME_STEP);

   ENUM_ORDER_TYPE order_type=
      (InpTradeDirection==Q_BUY_TRADE ? ORDER_TYPE_BUY : ORDER_TYPE_SELL);

   double margin=0.0;
   if(!OrderCalcMargin(order_type,g_symbol,InpLotSize,g_price,margin))
     {
      g_status="MARGIN CALCULATION FAILED";
      g_error_count++;
      return false;
     }

   g_required_margin=margin;
   g_free_margin_before=AccountInfoDouble(ACCOUNT_MARGIN_FREE);
   g_free_margin_after=g_free_margin_before-g_required_margin;

   if(g_free_margin_before>0.0)
      g_margin_use_pct=(g_required_margin/g_free_margin_before)*100.0;
   else
      g_margin_use_pct=0.0;

   double equity=AccountInfoDouble(ACCOUNT_EQUITY);
   double current_margin=AccountInfoDouble(ACCOUNT_MARGIN);
   double total_margin_after=current_margin+g_required_margin;

   if(total_margin_after>0.0)
      g_margin_level_after=(equity/total_margin_after)*100.0;
   else
      g_margin_level_after=0.0;

   g_position_value=g_contract_size*InpLotSize*g_price;

   ClassifyMarginUse();

   if(g_free_margin_after<0.0)
      g_status="INSUFFICIENT FREE MARGIN";
   else
      g_status="CALCULATION READY";

   return true;
  }

