int OnInit()
  {
   if(InpLotSize<=0.0 ||
      InpSafeMarginUsePct<0.0 ||
      InpWarningMarginUsePct<InpSafeMarginUsePct ||
      InpDangerMarginUsePct<InpWarningMarginUsePct)
     {
      Print("Quantora Margin Calculator MT5: Invalid input values.");
      return INIT_PARAMETERS_INCORRECT;
     }

   BuildPanel();
   UpdatePanel();

   EventSetTimer(MathMax(1,InpTimerSeconds));
   return INIT_SUCCEEDED;
  }

void OnDeinit(const int reason)
  {
   EventKillTimer();
   DeletePanel();
  }

void OnTick()
  {
   UpdatePanel();
  }

void OnTimer()
  {
   UpdatePanel();
  }

void OnChartEvent(const int id,
                  const long &lparam,
                  const double &dparam,
                  const string &sparam)
  {
   if(id!=CHARTEVENT_OBJECT_CLICK)
      return;

   if(sparam==g_prefix+"REFRESH")
     {
      g_status="RECALCULATING";
      UpdatePanel();
     }
   else if(sparam==g_prefix+"RESET")
     {
      g_error_count=0;
      g_status="READY";
      UpdatePanel();
     }
  }

