  {
   EventKillTimer();
   DeletePanel();
  }

void OnTick()
  {
   UpdatePanel();
  }

void OnTimer()
  {
   UpdatePanel();
  }

void OnChartEvent(const int id,
                  const long &lparam,
                  const double &dparam,
                  const string &sparam)
  {
   if(id!=CHARTEVENT_OBJECT_CLICK)
      return;

   if(sparam==g_prefix+"REFRESH")
     {
      g_status="RECALCULATING";
      UpdatePanel();
     }
   else if(sparam==g_prefix+"RESET")
     {
      g_error_count=0;
      g_status="READY";
      UpdatePanel();
     }
  }

